const masses = [60.05, 135.13, null, 180.16, 100.09, 74.09, 44.009, null, 192.12, 111.10, 134.13, 46.07, 180.16, 151.13, null, 34.015, 342.30, 58.320, 16.043, 32.042, 60.05, 63.013, 227.09, 44.013, 97.995, 56.106, 58.44, 84.007, 105.988, 39.997, 74.44, 342.30, 98.08, 126.11, 227.13, 18.015]
const massById = Object.fromEntries(DEFAULTS.map((item, index) => [item.id, masses[index]]))
const gases = new Set(['default-25', 'default-26', 'default-27'])
const liquids = new Set(['default-1', 'default-2', 'default-6', 'default-7', 'default-8', 'default-14', 'default-15', 'default-17', 'default-18', 'default-19', 'default-28'])
const propertyKeys = ['mass', 'state', 'melting', 'boiling', 'density', 'solubility']

function normalizeProperties(item, data) {
  const raw = data.physical
  const values = { ...raw, mass: massById[item.id], state: raw.state ?? (gases.has(item.id) ? 'gas' : liquids.has(item.id) ? 'liquid' : 'solid') }
  return Object.fromEntries(propertyKeys.map(key => {
    const input = values[key]
    const tuple = Array.isArray(input) ? input : null
    const value = tuple ? (key === 'solubility' ? bi(tuple[0], tuple[1]) : tuple[0]) : input
    const status = raw[`${key}Status`] ?? (value == null ? 'unavailable' : 'available')
    return [key, {
      value: status === 'available' ? value : null,
      unit: key === 'mass' && status === 'available' ? 'g/mol' : key === 'solubility' || key === 'state' ? null : tuple?.[1] ?? null,
      condition: status !== 'available' ? null : key === 'state' ? '20 °C, 1 atm' : key === 'solubility' ? 'room temperature' : key === 'density' ? tuple?.[2] ?? null : key === 'melting' || key === 'boiling' ? tuple?.[2] ?? '1 atm' : null,
      note: raw[`${key}Note`] ? bi(...raw[`${key}Note`]) : null,
      status,
      sourceIds: status === 'available' ? ['pubchem'] : [],
    }]
  }))
}

export const compoundProfiles = Object.fromEntries(DEFAULTS.filter(item => R[item.id]).map(item => {
  const data = R[item.id]
  const properties = normalizeProperties(item, data)
  return [item.id, {
    systematic: data.systematic, form: data.form, overview: data.overview, chemistry: data.chemistry, context: data.context,
    id: item.id,
    canonical: { formula: item.formula, smiles: item.smiles, pubchemUrl: item.pubchemUrl, wikidataId: item.wikidataId },
    properties,
    sources: [{
      id: 'pubchem', name: 'PubChem', url: item.pubchemUrl,
      fields: ['systematic', 'form', ...Object.keys(data.overview), ...propertyKeys.filter(key => properties[key].status === 'available'), ...Object.keys(data.chemistry), ...Object.keys(data.context)],
      retrievedAt: compoundProfileEdition, version: `CID ${item.pubchemUrl.split('/').at(-1)}`,
    }],
  }]
}))

export function profileForCompound(compound) {
  const found = compoundProfiles[compound?.id]
  if (!found) return null
  if (compound.formula !== found.canonical.formula) return null
  const identifiers = ['pubchemUrl', 'smiles', 'wikidataId']
  const present = identifiers.filter(key => compound[key] != null && compound[key] !== '')
  return present.length > 0 && present.every(key => compound[key] === found.canonical[key]) ? found : null
}
